# Generated by MSM Code v1.0
from machine import Pin, PWM, ADC
import time
import neopixel
from servo360 import Servo360

# Configurables:
speed = 50 # in %, adjustable with knob 2
drop_time = 5 # seconds to spend dropping/raising spider
noise_sensitivity = 30 # noise threshold to trigger spider, adjustable with knob 1

# Knob 1
adc0 = ADC(Pin(0))
adc0.atten(ADC.ATTN_11DB)

# Knob 2
adc1 = ADC(Pin(1))
adc1.atten(ADC.ATTN_11DB)

# Servo 1
sv1 = Servo360(6)
sv1.stop() # clean state

led_np = neopixel.NeoPixel(Pin(10), 2)  # onboard RGB LEDs
led_tpl = [0,0,0] # off by default
led_tpl2 = [0,0,0] # pixel 2

# Button 1
button1 = Pin(4, Pin.IN, Pin.PULL_UP)
button2 = Pin(5, Pin.IN, Pin.PULL_UP)

# Analog microphone as a noise sensor (ensure the pot arrow is pointing fully left on the board, NW for more sensitivity)
mic = ADC(Pin(3))  # Connect AOUT to GPIO 36
mic.atten(ADC.ATTN_11DB)  # Set attenuation for 0-3.3V range

# Helper function for mapping a value within one range of numbers to the relative value in another range of numbers
def msm_map(x, in_min, in_max, out_min, out_max):
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min

# Buttons lower/raise the drop time
def adjustDropTime():
    global led_tpl, drop_time
    if button1.value() == 0:
        drop_time -= 1
    
    elif button2.value() == 0:
        drop_time += 1
    
    if drop_time < 1:
        drop_time = 1
    elif drop_time > 10:
        # max drop time is 10 seconds because that's crazy
        drop_time = 10
        
    # blue for drop time
    led_tpl2[2] = int(msm_map(drop_time, 1, 10, 0, 50))
    time.sleep_ms(200) # give user a chance to let go of button
        
# Read knob 2 position for spider movement speed (%)
def adjustSpeed():
    global led_tpl, speed
    knob = adc1.read_u16()
    speed = int(msm_map(knob, 0, 65535, 0, 100))
    # adjust red for speed
    led_tpl[0] = int(msm_map(speed, 0, 100, 0, 50))

# Read knob 1 position for mic noise sensitivity
def adjustMic():
    global led_tpl, noise_sensitivity
    knob = adc0.read_u16()
    noise_sensitivity = int(msm_map(knob, 0, 65535, 10, 200))
    # adjust green for noise
    led_tpl[1] = int(msm_map(noise_sensitivity, 10, 200, 0, 50))

def checkMovement():
    # If the mic pics up sufficient noise, drop the spider.
    global led_np

    sound_level = mic.read()
    #print('Sound level: %d, target: %d' % (sound_level, noise_sensitivity))
    if sound_level > noise_sensitivity:
        return True
    
    else:
        return False

# In order to support changing speed and pos while spider is moving around, use steps instead of blocking fn calls
while True:
    adjustMic()
    adjustSpeed()
    adjustDropTime() # note this adds a 100ms delay to avoid bouncing buttons
    
    # set pixel 1 to the status color and display it
    led_np[0] = led_tpl
    led_np[1] = led_tpl2
    led_np.write()
   
    # not reading changes to drop speed/time because then it won't rewind the correct amount.
    if checkMovement():
        sv1.forward(speed)
        time.sleep(drop_time)
        sv1.stop()
        time.sleep(5)
        sv1.reverse(speed)
        time.sleep(drop_time)
        sv1.stop()
    
    # clock delay to prevent things from flying away...?
    time.sleep_ms(5)
